#include "ReagentWorks.h"
#include "Power.h"
#include "WaterWorks.h"
#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace aftertaste;using K=MachineKind;using E=EnergyMedium;
static int checks=0;static void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
static Factory empty(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.water=20;f.electricity=1000;return f;}
static Machine& device(Factory& f,Position p,K k){Machine m;m.kind=k;initialisePowerDevice(m);return f.machines.emplace(p,m).first->second;}
static Batch food(Factory& f,const std::string& ingredient,double grams){Batch b;b.id=f.nextId++;addIngredient(b.food,ingredient,grams,f.nextComponent++,f.nextOperation++);b.matter=projectCell(b.food);return b;}
static void advance(Factory& f,int n){for(int i=0;i<n;i++){++f.tick;f.beginPowerStep();f.finishPowerStep();}}
static int westAC(const FactoryState& f){int n=0;for(const auto& [p,ls]:f.energyLinks)if(p.x<-9&&p.y<7)for(const auto& l:ls)if(l.medium==E::AC)n++;return n;}
static const std::array<Position,34> campusSlots={Position{0,1},{1,1},{0,2},{1,2},{2,2},{3,2},{3,1},{0,3},{1,3},{2,3},{4,2},{0,5},{1,5},{2,5},{3,5},{4,5},{5,5},{6,8},{5,6},{1,4},{7,4},{8,4},{9,4},{0,8},{1,8},{2,8},{3,8},{4,8},{5,8},{7,8},{2,6},{3,6},{2,9},{3,9}};
int main(int argc,char** argv){try{
 {Factory f;auto plan=Factory::powerDistrictBlueprint();require(plan.width==10&&plan.height==7,"all generation fits the tighter 10 by 7 module");for(const auto& n:plan.links)require(n.link.medium==E::Heat||n.link.medium==E::Cooling,"the rack contains no internal electrical cable, water pipe or working-fluid conduit");require(westAC(f)==2,"one straight two-cell lead reaches the existing factory AC trunk");
 Position lamp{};bool found=false;for(const auto& [p,m]:f.machines)if(m.kind==K::GrowLight){lamp=p;found=true;break;}require(found,"demo provides an actual remote farm load");f.tick++;f.beginPowerStep();require(f.powerAvailable(lamp,machineSpec(K::GrowLight).power),"contact bank exports real electricity to the farm");f.usePower(lamp,machineSpec(K::GrowLight).power);f.finishPowerStep();require(f.energyLink({-11,1},E::AC)->flow>0&&f.energyLink({-10,1},E::AC)->flow>0,"actual load crosses the single short export cable");
 f.at({powerRackOrigin.x+9,powerRackOrigin.y+3})->enabled=false;f.tick++;f.beginPowerStep();require(!f.powerAvailable(lamp,machineSpec(K::GrowLight).power),"opening the output breaker isolates the factory without a hidden parallel feed");f.finishPowerStep();}
 {auto f=empty();device(f,{0,0},K::BatteryRack).power.store[size_t(E::DC)]=100;device(f,{1,0},K::Inverter);auto& pump=device(f,{1,1},K::FeedPump);auto& boiler=device(f,{2,1},K::BiomassBoiler);boiler.item=food(f,"cocoa",100);boiler.automatic=false;advance(f,3);double imported=20-f.water,total=0;for(const auto& [p,m]:f.machines)for(E e:{E::Water,E::Steam,E::Exhaust})total+=m.power.store[size_t(e)];require(boiler.power.store[size_t(E::Steam)]>0&&f.energyLinks.empty(),"docked feed-water manifold runs a real boiler without a water pipe");require(std::abs(total-imported)<1e-6&&imported<=20,"return-water contacts conserve the real supplied working fluid");require(f.powerContactFlow({1,1},{2,1},E::Water)>0,"water transfer is measured at the physical coupling");pump.enabled=false;advance(f,1);require(boiler.power.flow==0,"isolating the feed pump closes its manifold and stops fresh boiler work");require(!powerContactSupports(K::SolarPanel,K::FeedPump,E::Water),"solar edges remain DC-only");}
 {auto f=empty();auto& tank=device(f,{0,0},K::HeatTank);tank.power.store[size_t(E::Heat)]=50;auto& heater=device(f,{0,-2},K::Heater);heater.item=food(f,"brine",100);device(f,{-2,-2},K::GridInlet);PowerLink l;l.ports=15;l.medium=E::Heat;f.energyLinks[{0,-1}].push_back(l);l.medium=E::AC;f.energyLinks[{-1,-2}].push_back(l);f.beginPowerStep();double demand=machineSpec(K::Heater).power;require(f.powerAvailable({0,-2},demand),"top heat tap and AC feed meet a real heater load");f.usePower({0,-2},demand);f.finishPowerStep();require(tank.power.store[size_t(E::Heat)]<49.8&&f.energyLink({0,-1},E::Heat)->flow>0,"the additional tank outlet supplies measured finite heat");}
 if(argc>1){std::ifstream in(argv[1]);json j;in>>j;auto before=j.at("factory").get<FactoryState>();Factory f;f.storageFile=argv[1];require(f.load(),"migrate the supplied version 15 contact campus");std::map<Position,Position> moved;auto plan=Factory::powerDistrictBlueprint();for(size_t n=0;n<campusSlots.size();n++)moved[{powerCampusOrigin.x+campusSlots[n].x,powerCampusOrigin.y+campusSlots[n].y}]={powerRackOrigin.x+plan.parts[n].at.x,powerRackOrigin.y+plan.parts[n].at.y};for(const auto& n:Factory::nuclearLabBlueprint().parts)moved[{powerCampusLabOrigin.x+n.at.x,powerCampusLabOrigin.y+n.at.y}]={powerRackLabOrigin.x+n.at.x,powerRackLabOrigin.y+n.at.y};require(f.machines.size()==before.machines.size()+12+Factory::reagentWorksBlueprint().parts.size(),"the tighter layout retains all equipment");for(const auto& [p,m]:before.machines){auto q=moved.count(p)?moved.at(p):p;auto expected=m;if(moved.count(p)&&m.kind==K::PowerCondenser)expected.dir=1;require(f.at(q)&&json(*f.at(q))==json(expected),"live food, fuel, energy, wear and readings remain exact; only condenser sockets turn");}auto expected=before;expected.machines=f.machines;expected.energyLinks=f.energyLinks;expected.blueprints=f.blueprints;require(json(expected)==json(static_cast<const FactoryState&>(f)),"clock, input buffers, crops, records and other state are unchanged");require(westAC(f)==2&&westAC(before)>20,"saved factory removes the collector/perimeter wiring instead of hiding it");std::cout<<"Western AC cable cells: "<<westAC(before)<<" -> "<<westAC(f)<<"\n";
 for(int mutation=0;mutation<3;mutation++){auto custom=before;if(mutation==0)custom.energyLinks.at({-12,0}).front().rating+=1;if(mutation==1)custom.machines[{-13,4}]=Machine{};if(mutation==2)custom.machines.at({-23,-3}).dir=1;auto snap=json(custom);require(!dockDefaultPowerRackIn(custom)&&json(custom)==snap,"custom work prevents rearrangement atomically");}
 auto file=std::filesystem::temp_directory_path()/"aftertaste-contact-rack.json";f.storageFile=file;require(f.save(),"save tighter rack");Factory loaded;loaded.storageFile=file;require(loaded.load()&&json(static_cast<const FactoryState&>(loaded))==json(static_cast<const FactoryState&>(f)),"reload cannot move the rack or duplicate fuel/energy");std::filesystem::remove(file);
 }
 std::cout<<"PASS contact power rack: "<<checks<<" checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL contact power rack: "<<e.what()<<" (check "<<checks<<")\n";return 1;}}
